  for (const [k, v] of Object.entries(f)) {
    const cell = await shown(c.getByTestId(`claim-${k}`));
    if (k === 'ref' || k === 'tags') {
      const norm = k === 'ref' ? v.trim() : v.split(',').map((t) => t.trim().toLowerCase()).filter((t) => t)
