            <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
            <span data-testid="claim-overdue">{isOverdue(c, today) ? 'yes' : 'no'}</span>{' '}
            <span data-testid="claim-deferred">{isDeferred(c, today) ? 'yes' : 'no'}</span>{' '}
            <span data-testid="claim-deferred-until">{c.deferredUntil ?? ''}</span>{' '}
            <span data-testid="claim-proofs">{c.proofs}</span>{' '}
            <span data-testid="claim-split-from">{c.splitFrom ?? ''}</span>{' '}
            <ClaimStatusActions key={`${sheet}:${c.id}`} sheet={sheet} claim={c} onEdit={() => setEditing(String(c.id))}>
              {claim?.id === c.id && (
                <button type="button" data-testid="claim-cancel" onClick={() => setEditing(undefined)}>
                  Cancel
                </button>
              )}
            </ClaimStatusActions>
            <ol data-testid="claim-log">
              {(c.log ?? []).map((line, i) => (
                <li key={i} data-testid="claim-log-line">{line}</li>
              ))}
            </ol>
          </li>
        ))}
      </ul>
      {/* Keyed by the claim being edited, so opening an editor fills the form with its values. */}
      <ClaimForm key={`${sheet}:${claim?.id ?? ''}`} sheet={sheet} person={person} claim={claim} />
    </td>
  );
}

const ACTIONS = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'approve', label: 'Approve' },
  { action: 'reject', label: 'Reject' },
  { action: 'void', label: 'Void' },
  { action: 'resettle', label: 'Re-settle' },
] as const;

// A claim's status and the buttons that change it. A change its status does not allow is refused
// by the server and shows the claim's error, as is settling or approving a claim the signed-in user opened, a
// non-steward approving or rejecting a PENDING claim, an open, settle or void by a role the permission matrix does
// not allow, or rejecting one without a reason (typed beside the reject
// button). A clerk settling a claim whose due is above the clerk limit leaves it PENDING. The error goes as soon as
// the next action on the row is taken. Only a DRAFT can be edited: the edit button of any other claim shows the claim's error
// instead of opening its editor (an open claim is voided and added anew). A role the permission matrix allows (a steward, by the standing
// rule) moves a DRAFT, OPEN or PENDING
// claim to another person (picked beside the move button); anyone else moving it, or moving a SETTLED or VOID claim,
// shows the claim's error. A steward voids a SETTLED claim within 7 days of its settlement (its frozen due leaves
// the totals); anyone else, or a later day, shows the claim's error. A steward re-settles a SETTLED claim at the figure it would have today as an open claim
// bound by no statement; anyone else, or any other status, shows the claim's error. An OPEN claim is deferred until
// a date after the sheet's today (typed beside the defer button); any other status, a date not after today, or a claim
// in a closed period shows the claim's error. A deferred claim cannot be settled. The proof button raises the claim's
// proofs count by one; on a SETTLED or VOID claim it shows the claim's error. A claim whose due is above the proof
// threshold in force on its date cannot be settled or approved while it has no proof: that shows the claim's error.
// An OPEN claim splits off an amount (typed beside the split button; more than 0.00 and less than its amount) into a
// new OPEN claim; any other status, a deferred claim, a claim in a closed period or an amount out of range shows the
// claim's error. A steward re-dates an OPEN or PENDING claim (the date typed beside the re-date button); anyone
// else, any other status, a claim in a closed period, a new date in one or after the person's retirement shows the
// claim's error.
function ClaimStatusActions({ sheet, claim, onEdit, children }: {
  sheet: string; claim: Claim; onEdit: () => void; children: ReactNode;
}) {
  const [user] = useCurrentUser();
  const queryClient = useQueryClient();
  const [reason, setReason] = useState('');
  const change = useMutation({
    mutationFn: ({ action, reason }: { action: string; reason?: string }) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/${action}`
        + (reason === undefined ? '' : `?reason=${encodeURIComponent(reason)}`), undefined, user),
    onSuccess: (_, { action }) => {
      if (action === 'reject') setReason('');
      return queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
    },
  });
  const submitChange = useSubmitOnce(change);
  const people = usePeople();
  const others = (people.data ?? []).filter((p) => p.id !== claim.personId);
  const [moveTo, setMoveTo] = useState('');
  const target = others.find((p) => String(p.id) === moveTo) ?? others[0];
  const move = useMutation({
    mutationFn: (personId: number) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/person/${personId}`, undefined, user),
    onSuccess: () => Promise.all([
      queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) }),
      queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet) }),
    ]),
  });
  const submitMove = useSubmitOnce(move);
  const today = useSheetToday();
  const [deferTo, setDeferTo] = useState('');
  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/defer?until=${encodeURIComponent(until)}`, undefined, user),
    onSuccess: () => {
      setDeferTo('');
      return queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
    },
  });
  const submitDefer = useSubmitOnce(defer);
  const [redateTo, setRedateTo] = useState('');
  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/redate?date=${encodeURIComponent(date)}`, undefined, user),
    onSuccess: () => {
      setRedateTo('');
      return queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
    },
  });
  const submitRedate = useSubmitOnce(redate);
  const proof = useMutation({
    mutationFn: () => putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/proof`, undefined, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) }),
  });
  const submitProof = useSubmitOnce(proof);
  const [splitAmount, setSplitAmount] = useState('');
  const split = useMutation({
    mutationFn: (amount: string) =>
      putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/split?amount=${encodeURIComponent(amount)}`, undefined, user),
    onSuccess: () => {
      setSplitAmount('');
      return queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
    },
  });
  const submitSplit = useSubmitOnce(split);
  const [editRefused, setEditRefused] = useState(false);
  const action = change.variables?.action;
  const periods = usePeriods();
  const closed = !!periodOn(periods.data, claim.date)?.closed;
  return (
    <>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      <input
        data-testid="claim-reject-reason"
        placeholder="Reason to reject"
        value={reason}
        onChange={(e) => { setReason(e.target.value); change.reset(); defer.reset(); redate.reset(); split.reset(); proof.reset(); setEditRefused(false); }}
      />{' '}
      {ACTIONS.map(({ action, label }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setEditRefused(false);
            move.reset();
            defer.reset(); redate.reset(); split.reset();
            proof.reset();
            submitChange(action === 'reject' ? { action, reason } : { action });
          }}
        >
          {label}
        </button>
      ))}{' '}
      <select
        data-testid="claim-reassign-to"
        value={target ? String(target.id) : ''}
        onChange={(e) => { setMoveTo(e.target.value); move.reset(); change.reset(); defer.reset(); redate.reset(); split.reset(); proof.reset(); setEditRefused(false); }}
      >
        {others.map((p) => (
          <option key={p.id} value={String(p.id)}>{p.name}</option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="claim-reassign"
        disabled={move.isPending || !target}
        onClick={() => {
          change.reset();
          defer.reset(); redate.reset(); split.reset();
          proof.reset();
          setEditRefused(false);
          if (target) submitMove(target.id);
        }}
      >
        Move
      </button>{' '}
      <input
        data-testid="claim-defer-date"
        placeholder="Defer until YYYY-MM-DD"
        value={deferTo}
        onChange={(e) => { setDeferTo(e.target.value); defer.reset(); redate.reset(); split.reset(); change.reset(); move.reset(); proof.reset(); setEditRefused(false); }}
      />{' '}
      <button
        type="button"
        data-testid="claim-defer"
        disabled={defer.isPending}
        onClick={() => {
          change.reset();
          move.reset();
          proof.reset();
          split.reset();
          setEditRefused(false);
          submitDefer(deferTo);
        }}
      >
        Defer
      </button>{' '}
      <input
        data-testid="claim-date-new"
        placeholder="Re-date to YYYY-MM-DD"
        value={redateTo}
        onChange={(e) => { setRedateTo(e.target.value); redate.reset(); defer.reset(); split.reset(); change.reset(); move.reset(); proof.reset(); setEditRefused(false); }}
      />{' '}
      <button
        type="button"
        data-testid="claim-redate"
        disabled={redate.isPending}
        onClick={() => {
          change.reset();
          move.reset();
          defer.reset();
          proof.reset();
          split.reset();
          setEditRefused(false);
          submitRedate(redateTo);
        }}
      >
        Re-date
      </button>{' '}
      <button
        type="button"
        data-testid="claim-proof"
        disabled={proof.isPending}
        onClick={() => {
          change.reset();
          move.reset();
          defer.reset(); redate.reset(); split.reset();
          setEditRefused(false);
          submitProof(undefined);
        }}
      >
        Add proof
      </button>{' '}
      <input
        data-testid="claim-split-amount"
        placeholder="Amount to split off"
        inputMode="decimal"
        value={splitAmount}
        onChange={(e) => { setSplitAmount(e.target.value); split.reset(); change.reset(); move.reset(); defer.reset(); redate.reset(); proof.reset(); setEditRefused(false); }}
      />{' '}
      <button
        type="button"
        data-testid="claim-split"
        disabled={split.isPending}
        onClick={() => {
          change.reset();
          move.reset();
          defer.reset(); redate.reset();
          proof.reset();
          setEditRefused(false);
          submitSplit(splitAmount);
        }}
      >
        Split
      </button>{' '}
      <span onClickCapture={() => { change.reset(); move.reset(); defer.reset(); redate.reset(); split.reset(); proof.reset(); setEditRefused(false); }}>
        <button
          type="button"
          data-testid="claim-edit"
          onClick={() => {
            if (claim.status === 'DRAFT') onEdit();
            else setEditRefused(true);
          }}
        >
          Edit
        </button>
        {children}
      </span>
      {(change.isError || move.isError || defer.isError || redate.isError || proof.isError || split.isError || editRefused) && (
        <span data-testid="claim-error">
          {split.isError
            ? closed
              ? 'This claim is dated in a closed period, so it cannot be split.'
              : claim.status !== 'OPEN' || isDeferred(claim, today)
              ? `Only an open claim that is not deferred can be split; this one is ${isDeferred(claim, today) ? 'deferred' : claim.status}.`
              : `The amount to split off must be more than 0.00 and less than the claim's ${claim.amount}.`
            : proof.isError
            ? `A ${claim.status} claim cannot gain a proof.`
            : redate.isError
            ? claim.status !== 'OPEN' && claim.status !== 'PENDING'
              ? `Only an open or pending claim can be re-dated; this one is ${claim.status}.`
              : closed
              ? 'This claim is dated in a closed period, so it cannot be re-dated.'
              : 'Only a steward can re-date a claim, to a date in no closed period and not after the person\'s retirement.'
            : defer.isError
            ? closed
              ? 'This claim is dated in a closed period, so it cannot be deferred.'
              : claim.status !== 'OPEN'
              ? `Only an open claim can be deferred; this one is ${claim.status}.`
              : `A claim can only be deferred to a date after the sheet's today (${today ?? ''}).`
            : move.isError
            ? move.error instanceof HttpError && move.error.status === 403
              ? 'Your role is not allowed to move a claim to another person.'
              : `A ${claim.status} claim cannot move to another person.`
            : editRefused
            ? `Only a draft claim can be edited; void this ${claim.status} claim and add a new one.`
            : closed
            ? 'This claim is dated in a closed period, so its status cannot change.'
            : (action === 'approve' || action === 'reject') && change.error instanceof HttpError && change.error.status === 403
            ? 'Only a steward can approve or reject a pending claim.'
            : action === 'void' && claim.status === 'SETTLED' && change.error instanceof HttpError && change.error.status === 403
            ? 'Only a steward can void a settled claim.'
            : (action === 'open' || action === 'settle' || action === 'void') && change.error instanceof HttpError && change.error.status === 403
            ? `Your role is not allowed to ${action} a claim.`
            : action === 'void' && claim.status === 'SETTLED'
            ? 'A settled claim can be voided only within 7 days of its settlement.'
            : action === 'resettle' && change.error instanceof HttpError && change.error.status === 403
            ? 'Only a steward can re-settle a claim.'
            : action === 'resettle'
            ? `Only a settled claim can be re-settled; this one is ${claim.status}.`
            : (action === 'settle' || action === 'approve') && change.error instanceof HttpError && change.error.status === 422
            ? 'This claim\'s due is above the proof threshold, so it needs a proof before it can be settled or approved.'
            : action === 'settle' && isDeferred(claim, today)
            ? `This claim is deferred until ${claim.deferredUntil}, so it cannot be settled before then.`
            : action === 'settle' && claim.openedBy === user
            ? 'You opened this claim, so someone else must settle it.'
            : action === 'approve' && claim.openedBy === user && claim.status === 'PENDING'
            ? 'You opened this claim, so someone else must approve it.'
            : action === 'reject' && claim.status === 'PENDING' && reason.trim() === ''
            ? 'Give a reason to reject this claim.'
            : `That status change is not allowed for a ${claim.status} claim.`}
        </span>
      )}
    </>
  );
}

function ClaimForm({ sheet, person, claim }: { sheet: string; person: Person; claim?: Claim }) {
  const [user] = useCurrentUser();
  const [, setEditing] = useEditingClaim();
  const today = useSheetToday();
  const [amount, setAmount] = useState(claim?.amount ?? '');
  const [date, setDate] = useState(claim?.date ?? '');
  const [note, setNote] = useState(claim?.note ?? '');
  const [corrects, setCorrects] = useState(claim?.corrects == null ? '' : String(claim.corrects));
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (body: { amount: string; date: string; note: string; corrects: string }) =>
      claim
        ? putJson<Claim>(`${claimsPath(sheet)}/${claim.id}`, body, user)
        : postJson<Claim>(personClaimsPath(sheet, person.id), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
      if (claim) {
        setEditing(undefined);
      } else {
        setAmount('');
        setDate('');
        setNote('');
        setCorrects('');
      }
    },
  });
  const submit = useSubmitOnce(save);

  return (
    <form
      data-testid="claim-form"
      onSubmit={(e) => {
        e.preventDefault();
        submit({ amount, date, note, corrects });
      }}
    >
      <input
        data-testid="claim-form-amount"
        placeholder="Amount"
        inputMode="decimal"
        value={amount}
        onChange={(e) => { setAmount(e.target.value); save.reset(); }}
      />
      <input
        data-testid="claim-form-date"
        placeholder={today ?? 'YYYY-MM-DD'}
        value={date}
        onChange={(e) => { setDate(e.target.value); save.reset(); }}
      />
      <input
        data-testid="claim-form-note"
        placeholder="Note"
        value={note}
        onChange={(e) => { setNote(e.target.value); save.reset(); }}
      />
      <input
        data-testid="claim-form-corrects"
        placeholder="Corrects claim no."
        inputMode="numeric"
        value={corrects}
        onChange={(e) => { setCorrects(e.target.value); save.reset(); }}
      />
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
        {claim ? 'Save claim' : 'Add claim'}
      </button>
      {save.isError && (
        <span data-testid="claim-form-error">
          The amount must be a number with up to two decimals, and the date a calendar date not in a closed
          period nor after the person's retirement date; a negative amount is a correction and must name, by
          number, a settled claim of this person (only a correction may); only a draft claim can be edited.
        </span>
      )}
    </form>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 20, Component: ClaimsHeader }),
  PersonCells.fill({ order: 20, Component: PersonClaims }),
];
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** A claim's status: DRAFT to start, then OPEN and SETTLED; a clerk settling one above the clerk limit leaves it
 *  PENDING, until a steward approves it (SETTLED) or rejects it (OPEN again); a DRAFT, OPEN or PENDING claim can be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim as the store holds it: the amount with two decimals, the date (YYYY-MM-DD), the note, the status and
 *  the number given when it was opened (the sheet's next, or the next in its period: P1-1, X-1; null for a claim never opened; a voided claim keeps it) and the due fixed when it was
 *  settled (null when it has none: its due is live), and who opened it (null when never opened); whether its person's last statement binds it, and the
 *  figure it binds it to (null: n/a); the number of the settled claim of the same person it corrects (null when it is not
 *  a correction — a correction is a claim with a negative amount); the date its rounding goes by (a correction's is the
 *  date of the claim it corrects, else its own). */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  /** Its due-by (YYYY-MM-DD), fixed when it was created: its date plus the terms of its person's grade then. */
  dueBy: string;
  /** Its status log, oldest first: one line per status it has had, `<STATUS> by <user> on <date> due=<due>`. */
  log: string[];
  /** The date it is deferred until (YYYY-MM-DD), or null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs it has: raised by one at a time (not on a SETTLED or VOID claim). */
  proofs: number;
  /** The number of the claim it was split off from, or null when it was not made by a split. */
  splitFrom: string | null;
};

/** Whether a claim is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the live totals). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a claim shows and totals the figure its person's last statement bound it to: it is bound and not PENDING
 *  (a PENDING claim shows its live figure, and is bound again if rejected). */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** Whether a claim is deferred on the sheet's today: it is OPEN and deferred until a date after it. Until then it
 *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
export const isDeferred = (c: Claim, today: string | undefined) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do, but not a
 *  deferred one. */
export const counts = (c: Claim, today: string | undefined) => (isOpen(c) || c.status === 'SETTLED') && !isDeferred(c, today);

/** A hold: from a date on, to a date (YYYY-MM-DD, inclusive; null: open-ended). */
export type Hold = { from: string; to: string | null };

/** Each person's holds, by person id. */
export type Holds = Map<number, Hold[]>;

/** The holds of the people, by person id. */
export const holdsOf = (people: { id: number; holds: Hold[] }[] | undefined): Holds =>
  new Map((people ?? []).map((p) => [p.id, p.holds]));

/** Whether a hold of the claim's person covers its date. */
const heldOn = (c: Claim, holds: Holds) =>
  (holds.get(c.personId) ?? []).some((h) => h.from <= c.date && (h.to === null || c.date <= h.to));

/** Whether a claim counts toward the live totals: as `counts`, except its person's OPEN and PENDING claims dated
 *  within a hold of theirs, unless a statement binds them. */
export const countsLive = (c: Claim, holds: Holds, today: string | undefined) => counts(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c, holds));

/** The status a claim had at the end of a day (YYYY-MM-DD), as its status log records it (each line dated the sheet's
 *  today when the change was made); null when it had not been added by then. */
export function statusOn(c: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log ?? []) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S+$/.exec(line);
    if (m && m[2] <= day) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether a claim counts toward a period's live totals: as `countsLive`, taking the status it had at the end of
 *  the period's last day — not at all when it had not been added by then; a hold takes out only a claim that is
 *  still OPEN or PENDING and unbound now. */
export const countsAsOf = (c: Claim, holds: Holds, today: string | undefined, end: string) => {
  const status = statusOn(c, end);
  return status !== null && counts({ ...c, status }, today) && !(isOpen(c) && !isBound(c) && heldOn(c, holds));
};

export const claimsQueryKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/claims`;

export const personClaimsPath = (sheetId: string, personId: number) =>
  `/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/claims`;

/** Every claim on the sheet, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Claim[]>(claimsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** An amount ("12.50") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** A sum of the counted (OPEN, PENDING and SETTLED) claims' amounts, with two decimals; unbound OPEN claims dated
 *  within a hold of their person are left out. */
export function sumOf(claims: Claim[], held: Holds, today: string | undefined): string {
  return (claims.filter((c) => countsLive(c, held, today)).reduce((n, c) => n + cents(c.amount), 0) / 100).toFixed(2);
}

/** A claim's due-by (YYYY-MM-DD), fixed when it was created. */
export const dueByOf = (c: Claim): string => c.dueBy;

/** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by is before the sheet's today. */
export const isOverdue = (c: Claim, today: string | undefined) =>
  isOpen(c) && !isDeferred(c, today) && today !== undefined && dueByOf(c) < today;

/** The id of the claim whose editor is open (search param `editClaim`), or '' for none. */
export const useEditingClaim = () => useSearchParam('editClaim', asString);

/** The ids of the selected claims (search param `selectedClaims`, comma-separated), a toggle for one, and a
 *  clear. The toggle works from the URL as it is when it runs, so quick clicks in a row each keep the others'. */
export function useSelectedClaims() {
  const [ids] = useSearchParam('selectedClaims', asIds);
  const navigate = useNavigate();
  const update = (change: (ids: Set<number>) => void) =>
    void navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        const set = new Set(asIds(prev.selectedClaims));
        change(set);
        if (set.size === 0) delete next.selectedClaims;
