393	      if (claim) {
394	        setEditing(undefined);
395	      } else {
396	        setAmount('');
397	        setDate('');
398	        setNote('');
399	        setCorrects('');
400	      }
401	    },
402	  });
403	  const submit = useSubmitOnce(save);
404	
405	  return (
