422	        placeholder={today ?? 'YYYY-MM-DD'}
423	        value={date}
424	        onChange={(e) => { setDate(e.target.value); save.reset(); }}
425	      />
426	      <input
427	        data-testid="claim-form-note"
428	        placeholder="Note"
429	        value={note}
430	        onChange={(e) => { setNote(e.target.value); save.reset(); }}
431	      />
432	      <input
433	        data-testid="claim-form-corrects"
434	        placeholder="Corrects claim no."
435	        inputMode="numeric"
