import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The signed-in name and the active sheet id live in the URL (search params `user` and `sheet`).
// Everything else in the app is kept per sheet: a feature reads the sheet id from here and keys
// its queries under ['sheet', sheetId, ...], so loading a sheet re-reads all of them.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

// The active sheet as the store holds it: its id, its today and whether it is archived (then every
// change on it is refused). Every date decision and default
// date in the app uses the sheet's today (useSheetToday), never the browser's clock.
export type SheetInfo = { id: string; today: string; archived: boolean };

export const sheetQueryKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

export function useSheetInfo() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: sheetQueryKey(sheet ?? ''),
    queryFn: () => getJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}`),
    enabled: !!sheet,
  });
}

/** The sheet's today (YYYY-MM-DD), or undefined until the sheet is loaded. */
export const useSheetToday = () => useSheetInfo().data?.today;
import { useCallback, useState, useSyncExternalStore } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { AppSession } from '../../slots/defs/appSession';
import { useCurrentSheet, useCurrentUser } from './session';

// Whether every query kept for the sheet has been read at least once since it was (re-)loaded — so the
// sheet's id shows only once the screen holds what the store holds for it, not the empty or old data
// before. A refetch that keeps the data it had (after a change) does not hide it.
function useSheetRead(sheet: string | undefined): boolean {
  const queryClient = useQueryClient();
  const cache = queryClient.getQueryCache();
  const subscribe = useCallback((onChange: () => void) => cache.subscribe(onChange), [cache]);
  return useSyncExternalStore(subscribe, () => {
    if (!sheet) return false;
    const queries = cache.findAll({ queryKey: ['sheet', sheet] });
    return queries.length > 0 && queries.every((q) => q.state.status !== 'pending' || q.isDisabled());
  });
}

// Choose a sheet by typing its id and loading it. Loading (again) re-reads everything kept for it.
function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [id, setId] = useState('');
  const queryClient = useQueryClient();
  const load = useMutation({
    mutationFn: (sheetId: string) => putJson<{ id: string }>(`/api/sheets/${encodeURIComponent(sheetId)}`),
    onSuccess: async (loaded) => {
      // Drop what was read for it before, so the screen shows the store's data, never an older copy.
      await queryClient.resetQueries({ queryKey: ['sheet', loaded.id] });
      setSheet(loaded.id);
    },
  });
  const submit = useSubmitOnce(load);
  const read = useSheetRead(sheet);

  if (!user) return null;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (id.trim()) submit(id.trim());
      }}
    >
      <input data-testid="sheet-id-input" placeholder="Sheet id" value={id} onChange={(e) => { setId(e.target.value); load.reset(); }} />
      <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
        Load sheet
      </button>
      {sheet && read && (
        <span>
          Sheet <strong data-testid="sheet-current-id">{sheet}</strong>
        </span>
      )}
      {load.isError && <span data-testid="sheet-load-error">Could not load the sheet.</span>}
    </form>
  );
}

export const contribution = AppSession.fill({ order: 10, Component: SheetPicker });
import { useState } from 'react';
import { AppSession } from '../../slots/defs/appSession';
import { useCurrentUser } from './session';

// Sign in by typing a name (no password); the signed-in name shows once in.
function SignIn() {
  const [user, setUser] = useCurrentUser();
  const [name, setName] = useState('');

  if (user) {
    return (
      <span>
        Signed in as <strong data-testid="current-user">{user}</strong>
      </span>
    );
  }
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (name.trim()) setUser(name.trim());
      }}
    >
      <input data-testid="signin-name" placeholder="Your name" value={name} onChange={(e) => setName(e.target.value)} />
      <button type="submit" data-testid="signin-submit">
        Sign in
      </button>
    </form>
  );
}

export const contribution = AppSession.fill({ order: 0, Component: SignIn });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { AppSession } from '../../slots/defs/appSession';
import { useCurrentSheet, useCurrentUser, useSheetInfo, sheetQueryKey, type SheetInfo } from './session';

// The sheet's today: shown and changeable here. Changing it re-reads the whole sheet, since every
// date decision in the app depends on it. The sheet is archived here too (a steward only); the two
// share the sheet's one error element, which either action clears.
function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const info = useSheetInfo();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (today: string) =>
      putJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}/today`, { today }, user),
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetQueryKey(saved.id), saved);
      await queryClient.invalidateQueries({ queryKey: ['sheet', saved.id] });
    },
  });
  const submit = useSubmitOnce(save);
  const archive = useMutation({
    mutationFn: () => putJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}/archive`, undefined, user),
    onSuccess: (saved) => queryClient.setQueryData(sheetQueryKey(saved.id), saved),
  });
  const submitArchive = useSubmitOnce(archive);
  const shown = info.data?.id === sheet ? info.data : undefined;

  if (!user || !sheet) return null;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        submit(date.trim());
      }}
    >
      <span>
        Today <strong data-testid="sheet-today">{shown ? shown.today : ''}</strong>
      </span>
      <input
        data-testid="sheet-today-input"
        placeholder="YYYY-MM-DD"
        value={date}
        onChange={(e) => { setDate(e.target.value); save.reset(); archive.reset(); }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      <span>
        Archived <strong data-testid="sheet-archived">{shown ? (shown.archived ? 'yes' : 'no') : ''}</strong>
      </span>
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => { save.reset(); submitArchive(undefined); }}
      >
        Archive sheet
      </button>
      {save.isError && <span data-testid="sheet-error">Could not change the sheet's today.</span>}
      {archive.isError && <span data-testid="sheet-error">Could not archive the sheet.</span>}
    </form>
  );
}

export const contribution = AppSession.fill({ order: 20, Component: SheetToday });

