test("claim lock scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-A", "3");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "3");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-16", "to": "2026-03-12"})).toBe(false);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "3"}));
  expect(await ui.addPatron(pg_uma, p_ada, "Ben")).toBe(true);
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  await ui.setToday(pg_uma, "2026-04-15");
  expect(await ui.addClaim(pg_uma, p_ben, {"amount": "10.25", "date": "2026-03-09"})).toBeNull();
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33"}));
  expect(await ui.claimAction(pg_uma, c_ben_0, "void")).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Ben,7.77,2026-03-20,a, b\nBen,0.40,,paste\nZed,3.33,2026-02-10,")).toBeNull();
  await ui.refresh(pg_uma);
  await ui.setToday(pg_uma, "2026-05-21");
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "3"})).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
  const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "99.95"}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  await ui.setToday(pg_uma, "2026-06-16");
  const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.35"}));
  await ui.refresh(pg_uma);
  expect(await ui.editClaim(pg_uma, c_ada_2, {"amount": "25.00"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ada, "Ben")).toBe(false);
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  const c_ada_3 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "12.50", "date": "2026-02-10"}));
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ada_3, "void")).toBe(true);
  expect(await ui.exportCsv(pg_uma)).toBe("name,grade,retired-from,due-total\nBen,C,,0.00\nAda,A,,4.00\n");
  await ui.refresh(pg_uma);
  await ui.refresh(pg_uma);
  await ui.expectAudit(sheet, [
  ]);
});

