package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a claim of the sheet by id. */
public class LoadClaim {
    public void load(@Val Sheet sheet, @PathVariable("claimId") String claimId, ClaimRepository repository,
            Out<Claim> claimOut) throws ClaimNotFoundException {
        Long id;
        try {
            id = Long.valueOf(claimId.trim());
        } catch (NumberFormatException e) {
            throw new ClaimNotFoundException(claimId);
        }
        claimOut.set(repository.findByIdAndSheetId(id, sheet.getId())
                .orElseThrow(() -> new ClaimNotFoundException(claimId)));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Saves the claim's changes; refuses them unless the claim is a DRAFT (an open claim is voided and added anew
 * instead), when its date, or the one it would move to, is in a closed period, and when it would move after its
 * person's retirement date, and a correction that does not name a settled claim of its person. */
public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            PeriodRepository periods, PersonRepository people) throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("Only a draft claim can be edited; void it and add a new one.");
        }
        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
        if (periods.isClosedOn(sheet.getId(), claim.getDate()) || periods.isClosedOn(sheet.getId(), date)) {
            throw new InvalidClaimException("No claim can be edited in a closed period.");
        }
        if (people.findById(claim.getPersonId()).map(p -> p.retiredOn(date)).orElse(false)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), claim.getPersonId(), input.corrects());
        claim.setAmount(input.amount());
        claim.setCorrects(input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setDate(date);
        claim.setNote(input.note());
        repository.saveAndFlush(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads the claim form from the body; refuses an amount that is missing or has more than two decimals, a date
 * that is not a calendar date, and a corrects that is not a claim number. A negative amount (a correction) must
 * name the claim it corrects, and only a negative amount may. A blank date is left for the sheet's today.
 */
public class ValidateClaim {

    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
        body.set(request == null ? ClaimRules.check(null, null, null, null)
                : ClaimRules.check(request.amount(), request.date(), request.note(), request.corrects()));
    }
}
package net.officefloor.hq.app.role;

import net.officefloor.hq.app.AuditUser;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;

/** The first step of every change: refuses it, before anything is read or written, when the signed-in name is a
 *  viewer on the sheet (a viewer sees everything and changes nothing). */
public class GuardViewer {
    public void guard(@PathVariable("sheetId") String sheetId,
            @RequestHeader(name = "X-User", required = false) String user, RoleRepository roles)
            throws ViewerRefusedException {
        if (Role.VIEWER.equals(roles.roleOf(sheetId, AuditUser.decode(user)))) {
            throw new ViewerRefusedException("A viewer cannot change anything on the sheet.");
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Val;

public class ApplyToday {
    public void apply(@Val LocalDate today, @Val Sheet sheet, SheetRepository repository) {
        sheet.setToday(today);
        repository.save(sheet);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimStatus {
    public void handle(@Parameter ClaimStatusException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
package net.officefloor.hq.app.claim;

/** A status change the claim's current status does not allow (or an unknown action). */
public class ClaimStatusException extends Exception {
    public ClaimStatusException(String message) {
        super(message);
    }
}

